import { OBJExporter } from 'three/addons/exporters/OBJExporter.js';
import { createScene } from './object.js';
import * as fs from 'fs';
import * as path from 'path';

// Create output directories
const outputBase = '/root/output';
const partMeshesDir = path.join(outputBase, 'part_meshes');
const linksDir = path.join(outputBase, 'links');

fs.mkdirSync(partMeshesDir, { recursive: true });
fs.mkdirSync(linksDir, { recursive: true });

// Initialize OBJ exporter
const exporter = new OBJExporter();

// Get the scene root
const root = createScene();

/**
 * Export a single mesh to OBJ format
 * We need to apply world transforms before exporting
 */
function exportMeshToOBJ(mesh) {
    // Clone the mesh to avoid modifying the original
    const clonedMesh = mesh.clone();

    // Apply the world matrix to geometry
    mesh.updateWorldMatrix(true, false);
    const worldMatrix = mesh.matrixWorld.clone();

    // Create a new mesh with cloned geometry
    const exportGeometry = mesh.geometry.clone();
    exportGeometry.applyMatrix4(worldMatrix);

    const exportMesh = new THREE.Mesh(exportGeometry);
    exportMesh.name = mesh.name;

    // Create a scene just for this mesh
    const exportScene = new THREE.Scene();
    exportScene.add(exportMesh);

    return exporter.parse(exportScene);
}

/**
 * Export an entire group (link) to a single OBJ file
 * This combines all meshes in the group with their transforms applied
 */
function exportGroupToOBJ(group) {
    const exportScene = new THREE.Scene();

    group.updateWorldMatrix(true, true);

    group.traverse((child) => {
        if (child.isMesh) {
            const exportGeometry = child.geometry.clone();
            child.updateWorldMatrix(true, false);
            exportGeometry.applyMatrix4(child.matrixWorld);

            const exportMesh = new THREE.Mesh(exportGeometry);
            exportMesh.name = child.name;
            exportScene.add(exportMesh);
        }
    });

    return exporter.parse(exportScene);
}

/**
 * Process a part group - extract individual meshes and save them
 */
function processPartGroup(group, partName) {
    const partDir = path.join(partMeshesDir, partName);
    fs.mkdirSync(partDir, { recursive: true });

    console.log(`\nProcessing part: ${partName}`);

    // Track mesh counts for naming
    const meshCounts = {};

    group.children.forEach((child) => {
        if (child.isMesh) {
            // Export individual mesh
            const meshName = child.name || 'unnamed_mesh';

            // Handle duplicate names
            if (meshCounts[meshName]) {
                meshCounts[meshName]++;
            } else {
                meshCounts[meshName] = 1;
            }

            const fileName = meshCounts[meshName] > 1
                ? `${meshName}_${meshCounts[meshName]}.obj`
                : `${meshName}.obj`;

            const objData = exportMeshToOBJ(child);
            const filePath = path.join(partDir, fileName);
            fs.writeFileSync(filePath, objData);
            console.log(`  - Saved mesh: ${fileName}`);
        } else if (child.isGroup) {
            // For nested groups (like cabins), process recursively
            // But save to the same part folder
            processNestedGroup(child, partDir);
        }
