/**
 * Export a single mesh to OBJ format
 * We need to apply world transforms before exporting
 */
function exportMeshToOBJ(mesh) {
    // Clone the mesh to avoid modifying the original
    const clonedMesh = mesh.clone();

    // Apply the world matrix to geometry
    mesh.updateWorldMatrix(true, false);
    const worldMatrix = mesh.matrixWorld.clone();

    // Create a new mesh with cloned geometry
    const exportGeometry = mesh.geometry.clone();
    exportGeometry.applyMatrix4(worldMatrix);

    const exportMesh = new THREE.Mesh(exportGeometry);
    exportMesh.name = mesh.name;

    // Create a scene just for this mesh
    const exportScene = new THREE.Scene();
    exportScene.add(exportMesh);

    return exporter.parse(exportScene);
}

/**
 * Export an entire group (link) to a single OBJ file
 * This combines all meshes in the group with their transforms applied
 */
function exportGroupToOBJ(group) {
    const exportScene = new THREE.Scene();

    group.updateWorldMatrix(true, true);

    group.traverse((child) => {
        if (child.isMesh) {
            const exportGeometry = child.geometry.clone();
            child.updateWorldMatrix(true, false);
            exportGeometry.applyMatrix4(child.matrixWorld);

            const exportMesh = new THREE.Mesh(exportGeometry);
